// src/data/compendiumRatings.ts
/**
 * Show quality verdicts and per-show song highlights derived from the
 * Deadhead's Taping Compendium notes in showNotes.ts.
 *
 * GENERATED — do not hand-edit. Regenerate or retune with
 *   node scripts/compendiumRatings/recalibrateTiers.js
 * Verify with
 *   node scripts/compendiumRatings/verifyQuotes.js
 * Every quote here is an exact substring of that date's note.
 *
 * 1553 shows judged; 269 carry a tier; 1496 carry highlights.
 * Tier cutoffs on the evidence score: 4.8 / 4 / 3.3.
 * Tier 1 = 3 stars, matching ClassicTier elsewhere.
 *
 * This is ONE source (a taping guide). It supplements, and never overrides,
 * the multi-source community consensus in classicShowsTiers.ts.
 */

import type { ClassicTier } from './classicShowsTiers';

export type CompendiumVerdict =
  | 'essential' | 'excellent' | 'notable' | 'ordinary' | 'poor' | 'insufficient';

export type HighlightAssessment =
  | 'legendary' | 'excellent' | 'notable' | 'rare' | 'negative';

export interface ShowHighlight {
  /** Song title as the Compendium names it. */
  song: string;
  /** Catalog title when the song resolves to songs.generated.ts, else undefined. */
  canonicalTitle?: string;
  assessment: HighlightAssessment;
  /** Short display phrase, grounded in `quote`. */
  reason: string;
  /** Verbatim excerpt from that date's show note. */
  quote: string;
}

export interface CompendiumEntry {
  verdict: CompendiumVerdict;
  confidence: 'high' | 'medium' | 'low';
  /** Evidence score behind the tier; null when the note is unassessable. */
  score: number | null;
  tier: ClassicTier | null;
  /** True when the note's praise is about the recording, not the playing. */
  tapeOnly: boolean;
  caveat?: string;
  /** One-line description of what stood out. */
  summary?: string;
  /** Verbatim excerpts backing the verdict. Absent only when the note supports none. */
  evidence?: string[];
  highlights: ShowHighlight[];
}

