/** Compendium-derived tier for a date, or null. */
export function getCompendiumTier(date: string): ClassicTier | null {
  return COMPENDIUM_RATINGS[date.split('T')[0]]?.tier ?? null;
}

/** Songs the Compendium singles out as standouts of that show. */
export function getShowHighlights(date: string): ShowHighlight[] {
  return COMPENDIUM_RATINGS[date.split('T')[0]]?.highlights ?? [];
}

/** One-line note on what stood out about that show, when the notes support one. */
export function getShowSummary(date: string): string | null {
  return COMPENDIUM_RATINGS[date.split('T')[0]]?.summary ?? null;
}

/**
 * Dates where classicShowsTiers.ts rates a show a classic but its Compendium
 * note actively undercuts that — the note is weak, or its praise is about the
 * tape rather than the playing. Surfaced for review; nothing is auto-demoted.
 */
export const CURATED_TIER_DISPUTES: ReadonlyArray<{
  date: string; curatedTier: ClassicTier; verdict: CompendiumVerdict;
  tapeOnly: boolean; caveat: string; summary: string;
}> = [
];
